
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_t_pbe1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_t_pbe1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.593736485930336e+00, -4.517097776657631e+00, -4.410108954669714e+00, -4.262744723952734e+00, -4.063717182954952e+00, -3.802568150162046e+00, -3.474240502343705e+00, -3.086619399647576e+00, -2.666010870859810e+00, -2.224180794098129e+00, -1.578617517396239e+00, -7.937944328337906e-01, -6.283173769070302e-01, -5.632283878937986e-01, -4.740454614858312e-01, -3.816432733426160e-01, -2.657024434496799e-01, -1.118998743763970e-01, -2.494542158501596e-02, -2.809001540776496e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


